@@ -0,0 +1,16 @@
+import { slugify } from '../lib/text.js';
+import { formatDate } from '../lib/date.js';
+
+export function createEventCard(event) {
+  if (event === null || typeof event !== 'object') {
+    throw new TypeError('Invalid event');
+  }
+  const title = typeof event.title === 'string' ? event.title.trim() : '';
+  if (!title) {
+    throw new TypeError('Invalid event title');
+  }
+  if (event.startsAt === null || event.startsAt === undefined || typeof event.startsAt === 'boolean') {
+    throw new TypeError('Invalid event date');
+  }
+  return { id: slugify(title), title, dateLabel: formatDate(event.startsAt) };
+}

