@@ -0,0 +1,14 @@
+import { createEventCard } from './event-card.js';
+
+// Indices of `events` in ascending startsAt order; ties keep input order.
+export function chronologicalOrder(events) {
+  return events
+    .map((event, index) => ({ index, time: new Date(event.startsAt).getTime() }))
+    .sort((a, b) => a.time - b.time || a.index - b.index)
+    .map(({ index }) => index);
+}
+
+export function buildAgenda(events) {
+  const cards = events.map((event) => createEventCard(event));
+  return chronologicalOrder(events).map((index) => cards[index]);
+}

